import{_ as a,o as t,c as o,a5 as s}from"./chunks/framework.BwlBv862.js";const p=JSON.parse('{"title":"复用与审查运行时变量","description":"","frontmatter":{"title":"复用与审查运行时变量","docId":"user.automations.variables","translationKey":"user.automations.variables","locale":"zh","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"20ba9e681b63ffa9aff2ff5d868738d242fd4eab4d520d9e08656760ee8361ba","translationRevision":"3b5bf05569394ae4cc42628131128b679f54631b55ca5394ef1ab496604a15b4","order":40},"headers":[],"relativePath":"zh/user/automations/variables.md","filePath":"zh/user/automations/variables.md","lastUpdated":1794611623000}'),r={name:"zh/user/automations/variables.md"};function l(i,e,d,n,c,u){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="reuse-and-review-runtime-variables" tabindex="-1">复用与审查运行时变量 <a class="header-anchor" href="#reuse-and-review-runtime-variables" aria-label="Permalink to &quot;复用与审查运行时变量 {#reuse-and-review-runtime-variables}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目标与前置条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>只修改一次共用值，就能在多个操作中复用。你需要 <strong>自动化 → 变量</strong>，以及支持相关变量操作的宿主。类型化编辑与经过审查的 Cloud 操作会按宿主能力显示；本地保存无需上传。</p><h2 id="save-a-local-value" tabindex="-1">保存本地值 <a class="header-anchor" href="#save-a-local-value" aria-label="Permalink to &quot;保存本地值 {#save-a-local-value}&quot;">​</a></h2><ol><li>添加名为 <code>showLabel</code> 的变量。键以字母或下划线开头，可包含字母、数字、点、下划线和连字符，最多 <code>64</code> 个字符。避免重复键。</li><li>支持类型化编辑时，选择文本并输入 <code>晚间直播</code>。其他支持的类型包括数字、布尔值、列表和秘密值。列表使用字符串 JSON 数组，例如 <code>[&quot;红色&quot;, &quot;蓝色&quot;]</code>。</li><li>选择 <strong>保存全局变量</strong>。修订冲突说明已保存的集合发生变化；请重新加载，并据此审查要进行的编辑。</li><li>在支持模板的操作字段中使用保存的值：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{{ globals.showLabel }}：{{ event.user.uniqueId }}</span></span></code></pre></div><ol start="5"><li>测试一个仅写日志的操作，查看渲染文本。修改 <code>showLabel</code>、再次保存，再运行新测试。现有操作定义可复用更新值，无需重新导入模板。</li></ol><p>模板的 <code>params</code> 在应用模板时替换；<code>globals</code> 则在执行时读取。缺失的运行时键会渲染为空文本，因此用作目标或标识符前，请验证拼写。使用字段的变量建议，选择适合其触发器的事件路径。</p><h2 id="review-cloud-changes-separately" tabindex="-1">单独审查 Cloud 变更 <a class="header-anchor" href="#review-cloud-changes-separately" aria-label="Permalink to &quot;单独审查 Cloud 变更 {#review-cloud-changes-separately}&quot;">​</a></h2><p>宿主支持时，变量的 <strong>更改</strong> 控件提供经过审查的原生发送、获取、应用/采纳及撤回操作。先保存本地编辑，再选择比较项、检查其类型和值，并明确选择所需方向。获取 Cloud 候选项与将它应用到本地是两个步骤；撤回共享值也不同于删除本地行。</p><p>秘密值或被阻止的值在比较中会被遮蔽，且不能通过此审查路径发送。不要为了绕过限制而将秘密值改成普通文本。</p><h2 id="expected-result-status-and-recovery" tabindex="-1">预期结果、状态与恢复 <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to &quot;预期结果、状态与恢复 {#expected-result-status-and-recovery}&quot;">​</a></h2><p>本地变量及按能力启用的审查式共享均可使用；本地保存从不自动上传。无效键、无效类型值和过期修订会阻止保存。重试前，请修正高亮字段或重新加载。账户故障见 <a href="./../cloud/account.html">Cloud 账户</a>，比较行为见<a href="./../cloud/changes.html">变更</a>。</p>',13)])])}const b=a(r,[["render",l]]);export{p as __pageData,b as default};
